/**
 * Resolves the Project object from a clicked .proj-row DOM element.
 * Uses data-project-id to look up the in-memory project list rather than
 * trusting any other DOM state, so event delegation stays safe.
 */
function resolveProjectFromRow(row) {
  if (!row) return null
  const projectId = row.dataset.projectId
  return (
    projects.find(function (project) {
      return project.id === projectId
    }) || null
  )
}

/** Renders a single project row as an HTML string for innerHTML assignment. */
function buildProjectRowHtml(project) {
  const isSelected = selectedProject && project.id === selectedProject.id
  const sessionCount = searchQuery.trim()
    ? deriveVisibleSessionsForProject(project).length
    : project.sessions.length
  const lastActive = project.sessions.reduce(function (max, s) {
    return s.updated > max ? s.updated : max
  }, '')
  const lastLabel = lastActive ? compactRelativeTime(lastActive) : ''
  return (
    '<div class="proj-row' +
    (isSelected ? ' sel' : '') +
    '" data-project-id="' +
    escapeHtml(project.id) +
    '" title="' +
    escapeHtml(project.path) +
    (lastActive ? '\n' + fmt(STRINGS.projectLastActive, { time: relativeTime(lastActive) }) : '') +
    '">' +
    '<span class="p-name">' +
    escapeHtml(compactPath(project.path)) +
    '</span>' +
    buildProjectOrgChipsHtml(project) +
    '<span class="p-last">' +
    lastLabel +
    '</span>' +
    '<span class="p-cnt">' +
    sessionCount +
    '</span>' +
    '<div class="p-actions">' +
    '<button class="p-act-btn p-menu-btn" title="' +
    escapeHtml(STRINGS.projectMoreActions) +
    '">⋯</button>' +
    '</div>' +
    '</div>'
  )
}

/** Looks up the deep-search match record for a given session ID, or null if not found. */
function getDeepMatchForSession(sessionId) {
  for (var i = 0; i < deepSearchMatches.length; i++) {
    if (deepSearchMatches[i].sessionId === sessionId) return deepSearchMatches[i]
  }
  return null
}

/** Returns an HTML snippet row showing the match count and text excerpt. Empty string when match is null. */
function buildDeepSnippetHtml(match) {
  if (!match) return ''
  const hitLabel =
    match.matchCount === 1
      ? fmt(STRINGS.sessionDeepHit, { n: match.matchCount })
      : fmt(STRINGS.sessionDeepHits, { n: match.matchCount })
  return (
    '<div class="s-deep-snippet">' +
    '<span class="s-deep-count">' +
    hitLabel +
    '</span>' +
    '<span class="s-deep-text">' +
    escapeHtml(match.snippet) +
    '</span>' +
    '</div>'
  )
}

/**
 * Returns the subset of projects that should appear in the left panel given
 * the current search query, active filters, and deep-search state.
 * In deep-search mode only projects that contain at least one transcript match are shown.
 */
function deriveVisibleProjects() {
  if (deepSearchActive) {
    if (deepSearchLoading) return []
    const matchedProjectIds = new Set(
      deepSearchMatches.map(function (m) {
        return m.projectId
      })
    )
    return projects.filter(function (p) {
      return matchedProjectIds.has(p.id)
    })
  }

  // Apply focus filter (defined in 17-rail.js; hoisted function declaration).
  var baseProjects = projects
  if (focusFilter) {
    baseProjects = projects.filter(function (project) {
      var focusSessions = getSessionsMatchingFocus(project)
      if (focusSessions === undefined) return false
      if (focusSessions === null) return true
      return focusSessions.length > 0
    })
  }

  const searchSpec = parseSearchQuery(searchQuery)
  const visibleProjects = searchSpecHasFilters(searchSpec)
    ? baseProjects.filter(function (project) {
        const projectTextMatches = projectMatchesSearch(project, searchSpec)
        if (projectTextMatches && searchSpec.reviewBucketIds.length === 0) return true
        return deriveVisibleSessionsForProject(project).length > 0
      })
    : baseProjects
  if (selectedProjectSort !== 'name') return visibleProjects

  return visibleProjects.slice().sort(function (left, right) {
    const pathComparison = compactPath(left.path).localeCompare(compactPath(right.path))
    return pathComparison || left.path.localeCompare(right.path)
  })
}

/** Re-renders the full project list panel from current state. */
function renderProjects() {
  const visibleProjects = deriveVisibleProjects()
  elements.projectCountLabel.textContent = fmt(STRINGS.projectsLabel, { n: visibleProjects.length })
  elements.projectList.innerHTML = visibleProjects.map(buildProjectRowHtml).join('')
}

/** Selects a project, clears the session selection, and re-renders both panels. */
function selectProject(project) {
  selectedProject = project
  selectedSession = null
  if (!searchQuery.trim()) selectedFilter = 'all'
  renderProjects()
  renderSessions()
  void refreshClaudeInstructionsAvailability(project)
  if (window.matchMedia('(max-width: 639px)').matches) {
    document.body.classList.add('narrow-sessions')
  }
}

elements.projectList.addEventListener('click', function (event) {
  const tagChip = event.target.closest('.p-tag')
  if (tagChip) {
    event.stopPropagation()
    var tag = tagChip.dataset.tag
    if (tag) {
      focusFilter =
        focusFilter && focusFilter.kind === 'tag' && focusFilter.tag === tag
          ? null
          : { kind: 'tag', tag: tag }
      synchronizeSelectedProjectWithView()
      renderRail()
      renderFocusBar()
      renderProjects()
      renderSessions()
    }
    return
  }

  const menuBtn = event.target.closest('.p-menu-btn')
  if (menuBtn) {
    event.stopPropagation()
    const project = resolveProjectFromRow(menuBtn.closest('.proj-row'))
    if (!project) return
    ctxProject = project
    ctxSession = null
    openContextMenu(menuBtn, [
      { action: 'project-new-session', label: STRINGS.projectCtxNewSession },
      { action: 'project-copy-path', label: STRINGS.projectCtxCopyPath },
      { type: 'separator' },
      { action: 'project-tag', label: STRINGS.sessionActionTag },
      { action: 'project-move-group', label: STRINGS.projectCtxMoveToGroup },
      { action: 'project-add-stack', label: STRINGS.projectCtxAddToStack },
    ])
    return
  }

  const project = resolveProjectFromRow(event.target.closest('.proj-row'))
  if (project) selectProject(project)
})

elements.projectSortSelect.addEventListener('change', function () {
  selectedProjectSort = elements.projectSortSelect.value
  renderProjects()
})
// ---------------------------------------------------------------------------
// Session view model and selection
// ---------------------------------------------------------------------------

/** Returns the sessions in a project that satisfy the given filter tab. */
function sessionsMatchingFilter(project, filter) {
  if (!project) return []
  const sessions = project.sessions

  if (filter === 'attention') {
    return sessions.filter(function (session) {
      const status = session.primaryStatus
      // Interrupted (pending tool calls from transcript analysis) is triage-only,
      // not actionable as a live "needs your input" signal. Live attention is now
      // detected via the session's liveActivity.attention field or waiting state.
      return !session.signals.archived && (status === 'expiring' || status === 'path-missing')
    })
  }
  if (filter === 'active') {
    return sessions.filter(function (session) {
      return !session.signals.archived && activeSessionIds.has(session.id)
    })
  }
  if (filter === 'archived') {
    return sessions.filter(function (session) {
      return session.signals.archived
    })
  }
  // The default "all" view intentionally excludes locally archived sessions.
  return sessions.filter(function (session) {
    return !session.signals.archived
  })
}

/** Returns true if any string in values contains the already-lowercased query. */
function valuesMatchSearch(values, normalizedQuery) {
  return values.some(function (value) {
    return (value || '').toLowerCase().includes(normalizedQuery)
  })
}

function normalizeReviewSearchToken(value) {
  var token = String(value || '')
    .toLowerCase()
    .replace(/^is:/, '')
  if (token === 'drift') return 'branch-drift'
  if (token === 'missing') return 'path-missing'
  if (token === 'context') return 'high-context'
  for (var i = 0; i < REVIEW_BUCKETS.length; i++) {
    if (REVIEW_BUCKETS[i].id === token) return token
  }
  return null
}

function getReviewBucket(bucketId) {
  for (var i = 0; i < REVIEW_BUCKETS.length; i++) {
    if (REVIEW_BUCKETS[i].id === bucketId) return REVIEW_BUCKETS[i]
  }
  return null
}

function primaryReviewBucket(session) {
  if (session.signals.archived) return null
  for (var i = 0; i < REVIEW_BUCKETS.length; i++) {
    if (REVIEW_BUCKETS[i].test(session)) return REVIEW_BUCKETS[i]
  }
  return null
}

function parseSearchQuery(query) {
  var reviewBucketIds = []
  var textParts = []
  var parts = String(query || '')
    .trim()
    .split(/\s+/)
    .filter(Boolean)

  for (var i = 0; i < parts.length; i++) {
    var part = parts[i]
    if (part.toLowerCase().startsWith('is:')) {
      var bucketId = normalizeReviewSearchToken(part)
      if (bucketId) {
        reviewBucketIds.push(bucketId)
        continue
      }
    }
    textParts.push(part)
  }

  return {
    raw: String(query || '').trim(),
    reviewBucketIds: reviewBucketIds,
    text: textParts.join(' ').toLowerCase(),
  }
}

function searchSpecHasFilters(searchSpec) {
  return !!(searchSpec.raw || searchSpec.text || searchSpec.reviewBucketIds.length > 0)
}

function sessionMatchesReviewBuckets(session, reviewBucketIds) {
  if (reviewBucketIds.length === 0) return true
  if (session.signals.archived) return false

  return reviewBucketIds.every(function (bucketId) {
    var bucket = getReviewBucket(bucketId)
    return bucket ? bucket.test(session) : true
  })
}

/** Returns true if the project's ID or path matches the textual search query. */
function projectMatchesSearch(project, searchSpec) {
  return !!searchSpec.text && valuesMatchSearch([project.id, project.path], searchSpec.text)
}

/** Returns true if any searchable field of the session matches the textual search query. */
function sessionMatchesSearchText(session, normalizedQuery) {
  return valuesMatchSearch(
    [
      session.id,
      session.name,
      session.alias,
      session.projectPath,
      session.gitBranch,
      session.currentBranch,
    ].concat(session.context.models || []),
    normalizedQuery
  )
}

/**
 * Returns sessions to display for a project given current filter, search, and deep-search state.
 * In deep-search mode returns only transcript-matched sessions for this project.
 */
function deriveVisibleSessionsForProject(project) {
  if (deepSearchActive) {
    const matchedIds = new Set(
      deepSearchMatches
        .filter(function (m) {
          return m.projectId === project.id
        })
        .map(function (m) {
          return m.sessionId
        })
    )
    return project.sessions.filter(function (s) {
      return matchedIds.has(s.id)
    })
  }

  // Apply focus filter (getSessionsMatchingFocus defined in 17-rail.js; hoisted).
  var focusSessions = getSessionsMatchingFocus(project)
  var sessions

  if (focusSessions === undefined || focusSessions === null) {
    // Project is in focus with no session-level restriction — apply pill filter normally.
    sessions = sessionsMatchingFilter(project, selectedFilter)
  } else {
    // Tag / specific-session stack focus — intersect with pill filter.
    var pilledIds = new Set(
      sessionsMatchingFilter(project, selectedFilter).map(function (s) {
        return s.id
      })
    )
    sessions = focusSessions.filter(function (s) {
      return pilledIds.has(s.id)
    })
  }

  const searchSpec = parseSearchQuery(searchQuery)
  if (!searchSpecHasFilters(searchSpec)) return sessions

  const projectTextMatches = projectMatchesSearch(project, searchSpec)
  if (projectTextMatches && searchSpec.reviewBucketIds.length === 0) return sessions

  return sessions.filter(function (session) {
    if (!sessionMatchesReviewBuckets(session, searchSpec.reviewBucketIds)) return false
    if (!searchSpec.text || projectTextMatches) return true
    return sessionMatchesSearchText(session, searchSpec.text)
  })
}

/** Returns the visible sessions for the selected project, sorted per the current sort selection. */
function deriveVisibleSessions() {
  const sessions = selectedProject ? deriveVisibleSessionsForProject(selectedProject) : []
  if (selectedSort === 'context') {
    return sessions.slice().sort(function (left, right) {
      const leftTokens = left.context.latestContextTokens ?? -1
      const rightTokens = right.context.latestContextTokens ?? -1
      return rightTokens - leftTokens || right.updated.localeCompare(left.updated)
    })
  }
  if (selectedSort !== 'risk') return sessions

  return sessions.slice().sort(function (left, right) {
    const leftRank = RISK_RANK[left.primaryStatus] != null ? RISK_RANK[left.primaryStatus] : 4
    const rightRank = RISK_RANK[right.primaryStatus] != null ? RISK_RANK[right.primaryStatus] : 4
    if (leftRank !== rightRank) return leftRank - rightRank
    return right.updated.localeCompare(left.updated)
  })
}

/**
 * Ensures selectedProject is still visible after a filter/search/data change.
 * Falls back to the first visible project when the current selection is hidden.
 * This prevents a stale project from staying "active" while showing zero sessions.
 */
function synchronizeSelectedProjectWithView() {
  const visibleProjects = deriveVisibleProjects()
  if (
    selectedProject &&
    visibleProjects.some(function (project) {
      return project.id === selectedProject.id
    })
  ) {
    return
  }

  selectedProject = visibleProjects[0] || null
  selectedSession = null
  renamingSessionId = null
  if (selectedProject) void refreshClaudeInstructionsAvailability(selectedProject)
}

/** Resolves a Session from a clicked .sess-row DOM element using data-session-id lookup. */
function resolveSessionFromRow(row) {
  if (!row || !selectedProject) return null
  const sessionId = row.dataset.sessionId
  return (
    selectedProject.sessions.find(function (session) {
      return session.id === sessionId
    }) || null
  )
}

/**
 * Rebinds the selection to freshly fetched data without forgetting a session
 * merely because search or filters currently hide it.
 */
function synchronizeSelectedSession() {
  if (!selectedSession || !selectedProject) return
  const refreshedSession = selectedProject.sessions.find(function (session) {
    return session.id === selectedSession.id
  })
  selectedSession = refreshedSession || null
  if (!selectedSession) renamingSessionId = null
}

/**
 * Marks a session as selected, updates the URL hash so the session is deep-linkable,
 * and toggles the .sel class on the relevant row without rebuilding the list.
 * Keeping row nodes stable preserves any in-progress rename input.
 */
function refreshExpandedSessionListIfNeeded(visibleSessions) {
  if (!isSessionInspectorExpanded(visibleSessions)) return false
  elements.sessionList.innerHTML = buildSessionRowHtml(selectedSession)
  return true
}

function selectSession(session) {
  selectedSession = session
  // Update URL so this session can be bookmarked or shared
  if (window.history && window.history.replaceState) {
    history.replaceState(null, '', '#' + session.id)
  }

  // Selection must not rebuild the list. Keeping row nodes stable preserves
  // inline rename text and browser double-click detection.
  elements.sessionList.querySelectorAll('.sess-row').forEach(function (row) {
    row.classList.toggle('sel', row.dataset.sessionId === session.id)
    const arrow = row.querySelector('.s-arrow')
    if (arrow) arrow.textContent = row.dataset.sessionId === session.id ? '▶' : ' '
  })
  const visibleSessions = deriveVisibleSessions()
  if (refreshExpandedSessionListIfNeeded(visibleSessions)) {
    renderInspector(visibleSessions)
    return
  }
  renderInspector(visibleSessions)
}
// ---------------------------------------------------------------------------
// Session filters and inspector
// ---------------------------------------------------------------------------

/** Returns session counts per filter tab for the selected project. */
function calculateFilterCounts() {
  if (!selectedProject) return {}
  return {
    active: sessionsMatchingFilter(selectedProject, 'active').length,
    all: sessionsMatchingFilter(selectedProject, 'all').length,
    archived: sessionsMatchingFilter(selectedProject, 'archived').length,
    attention: sessionsMatchingFilter(selectedProject, 'attention').length,
  }
}

/** Updates filter pill active state, counts, and tooltips. Hides the bar entirely when no project is selected. */
function renderFilterBar() {
  if (!selectedProject) {
    elements.filterBar.style.display = 'none'
    return
  }

  elements.filterBar.style.display = 'flex'
  if (elements.filterScopeLabel) elements.filterScopeLabel.textContent = STRINGS.filterScopeLabel
  const counts = calculateFilterCounts()
  elements.filterBar.querySelectorAll('.filter-pill').forEach(function (pill) {
    const filter = pill.dataset.filter
    const count = counts[filter] || 0
    pill.classList.toggle('active', filter === selectedFilter)
    pill.title = filterTooltip(filter)
    pill.innerHTML =
      filterLabel(filter) + (count > 0 ? '<span class="pill-cnt">' + count + '</span>' : '')
  })
}

/** Returns an HTML row string for the session inspector panel (label + value pair). */
function buildInspectorRowHtml(label, value, valueClass, valueAttributes) {
  return (
    '<div class="insp-row"><span class="insp-key">' +
    label +
    '</span><span class="insp-val' +
    (valueClass ? ' ' + valueClass : '') +
    '"' +
    (valueAttributes ? ' ' + valueAttributes : '') +
    '>' +
    value +
    '</span></div>'
  )
}

/** Looks up a session's live activity entry, or null when it is not active. */
function findLiveActivity(sessionId) {
  for (var i = 0; i < liveActivity.length; i++) {
    if (liveActivity[i].sessionId === sessionId) return liveActivity[i]
  }
  return null
}

/**
 * The activity state every web surface displays for an entry — the one place
 * that decides it, so the rail, the session list and the inspector can never
 * disagree with each other.
 *
 * The base reading is `entry.liveState`, resolved server-side by the shared
 * core that the TUI and the VS Code extension use too. The web then adds one
 * refinement the other surfaces do not attempt: it splits "attached but quiet"
 * into a plain quiet session and one that is specifically *waiting*.
 *
 * That refinement is gated on `stateIsReported`, because "waiting" reads as
 * "this needs you" and is only trustworthy when something actually reported
 * the turn boundary — a lock status field or a hook marker. Sessions with
 * neither (VS Code peer locks omit `status`) derive their state from
 * transcript recency, where a pause mid-tool-call is indistinguishable from a
 * finished turn. There the session stays on the shared reading rather than
 * claiming attention nothing can vouch for.
 */
function dotActivityState(entry) {
  if (!entry) return 'idle'
  var liveState = entry.liveState || 'attached'
  if (liveState === 'needs-input') return 'attention'
  if (liveState === 'working') return 'running'
  if (liveState === 'detached') return 'idle'
  // A recorded stop outranks the quiet-session refinements. "Waiting" reads as
  // "between turns" and hides that the turn was cut short; the user reported
  // exactly that as wrong.
  if (entry.endedByUserInterruption === true) return 'interrupted'
  if (entry.activityState === 'waiting' && entry.stateIsReported === true) return 'waiting'
  return 'attached'
}

/** The label that goes with a state from `dotActivityState`. */
function dotActivityLabel(state) {
  if (state === 'interrupted') return STRINGS.activityInterrupted
  if (state === 'attention') return STRINGS.activityNeedsInput
  if (state === 'running') return STRINGS.activityRunning
  if (state === 'waiting') return STRINGS.activityWaiting
  return STRINGS.activityIdle
}

/**
 * Builds the inspector "Activity" heartbeat row for an active session.
 * Returns an empty string when the session has no live activity entry.
 */
function buildInspectorHeartbeatHtml(session) {
  var entry = findLiveActivity(session.id)
  if (!entry) return ''
  var state = dotActivityState(entry)
  var stateLabel = dotActivityLabel(state)
  var tool =
    entry.lastToolName && state === 'running'
      ? ' <span class="activity-tool">' + escapeHtml(entry.lastToolName) + '</span>'
      : ''
  var value =
    '<span class="activity-dot ' + escapeHtml(state) + '"></span> ' + escapeHtml(stateLabel) + tool
  return buildInspectorRowHtml(
    STRINGS.inspRowActivity,
    value,
    'insp-activity',
    'title="' + escapeHtml(STRINGS.inspRowActivityTooltip) + '"'
  )
}

/** Returns the stable cache key for a session preview. */
function previewCacheKey(project, session) {
  return project.id + ':' + session.id
}

/** Fetches fresh Resume Card data while preserving any existing rendered card. */
function refreshSessionPreview(project, session, key, entry) {
  entry.refreshing = true
  requestJson('/api/sessions/' + project.id + '/' + session.id + '/preview')
    .then(function (preview) {
      sessionPreviewCache.set(key, { data: preview, state: 'ready' })
      if (
        selectedProject &&
        selectedProject.id === project.id &&
        selectedSession?.id === session.id
      ) {
        renderInspector(deriveVisibleSessions())
      }
    })
    .catch(function (error) {
      if (entry.data) {
        entry.refreshError = error.message
        entry.refreshing = false
        entry.stale = false
      } else {
        sessionPreviewCache.set(key, { error: error.message, state: 'error' })
      }
      if (
        selectedProject &&
        selectedProject.id === project.id &&
        selectedSession?.id === session.id
      ) {
        renderInspector(deriveVisibleSessions())
      }
    })
}

/** Starts loading Resume Card data for a session if it is not already cached. */
function ensureSessionPreview(project, session) {
  const key = previewCacheKey(project, session)
  const cached = sessionPreviewCache.get(key)
  if (cached) {
    if (cached.stale && !cached.refreshing) refreshSessionPreview(project, session, key, cached)
    return cached
  }

  const loadingEntry = { state: 'loading' }
  sessionPreviewCache.set(key, loadingEntry)
  refreshSessionPreview(project, session, key, loadingEntry)

  return loadingEntry
}

/** Marks cached previews stale so live refreshes do not blank the inspector while reloading. */
function markSessionPreviewsStale() {
  sessionPreviewCache.forEach(function (entry, key) {
    if (entry.state === 'ready' && entry.data) {
      entry.stale = true
      entry.refreshError = null
      return
    }
    if (entry.state !== 'loading') sessionPreviewCache.delete(key)
  })
}

/** Returns action buttons for the selected session. These mirror the row menu and keyboard shortcuts. */
function buildInspectorActionsHtml(session) {
  const deleteDisabled = activeSessionIds.has(session.id)
  const resumeDisabled = !session.signals.pathExists
  const isArchived = session.signals.archived
  return (
    '<div class="insp-actions">' +
    '<button class="insp-action primary" data-inspector-action="session-resume" title="' +
    escapeHtml(resumeDisabled ? STRINGS.resumePathUnavailable : STRINGS.inspBtnResumeTooltip) +
    '"' +
    (resumeDisabled ? ' disabled' : '') +
    '>' +
    STRINGS.inspBtnResume +
    '</button>' +
    '<button class="insp-action" data-inspector-action="session-handoff" title="' +
    escapeHtml(STRINGS.inspBtnHandoffTooltip) +
    '">' +
    STRINGS.inspBtnHandoff +
    '</button>' +
    '<button class="insp-action" data-inspector-action="session-rename" title="' +
    escapeHtml(STRINGS.inspBtnRenameTooltip) +
    '">' +
    STRINGS.inspBtnRename +
    '</button>' +
    '<button class="insp-action" data-inspector-action="session-archive" title="' +
    escapeHtml(isArchived ? STRINGS.inspBtnUnarchiveTooltip : STRINGS.inspBtnArchiveTooltip) +
    '">' +
    (isArchived ? STRINGS.inspBtnUnarchive : STRINGS.inspBtnArchive) +
    '</button>' +
    '<button class="insp-action danger" data-inspector-action="session-delete" title="' +
    escapeHtml(
      deleteDisabled ? STRINGS.inspBtnDeleteDisabledTooltip : STRINGS.inspBtnDeleteTooltip
    ) +
    '"' +
    (deleteDisabled ? ' disabled' : '') +
    '>' +
    STRINGS.inspBtnDelete +
    '</button>' +
    '</div>' +
    '<div class="insp-shortcuts">' +
    STRINGS.inspShortcuts +
    '</div>'
  )
}

function buildPreviewLabelHtml(label, icon) {
  return (
    '<div class="preview-label">' +
    (icon ? '<span class="preview-label-icon">' + icon + '</span>' : '') +
    '<span>' +
    label +
    '</span>' +
    '</div>'
  )
}

/** Returns one labelled Resume Card text block. */
function buildPreviewBlockHtml(label, text, blockClass, icon) {
  return (
    '<div class="preview-block' +
    (blockClass ? ' ' + blockClass : '') +
    '">' +
    buildPreviewLabelHtml(label, icon) +
    '<div class="preview-text">' +
    (text
      ? escapeHtml(text)
      : '<span class="preview-empty">' + STRINGS.previewNotFound + '</span>') +
    '</div>' +
    '</div>'
  )
}

/** Returns one labelled Resume Card block with a safe, tiny Markdown subset. */
function buildPreviewMarkdownBlockHtml(label, text, blockClass, icon) {
  return (
    '<div class="preview-block' +
    (blockClass ? ' ' + blockClass : '') +
    '">' +
    buildPreviewLabelHtml(label, icon) +
    '<div class="preview-markdown">' +
    (text
      ? renderPreviewMarkdown(text)
      : '<span class="preview-empty">' + STRINGS.previewNotFound + '</span>') +
    '</div>' +
    '</div>'
  )
}

/**
 * Maps AutomaticFactSource values to reader-friendly labels.
 * Returns the raw value for any unknown source so new sources surface visibly.
 */
function friendlySource(source) {
  if (source === 'summary-event') return 'compaction'
  if (source === 'assistant-tool' || source === 'tool-result') return 'tool result'
  if (source === 'attachment') return 'attachment'
  if (source === 'transcript-event') return 'transcript'
  return source || ''
}

/** Returns the latest Claude-native plan section when the transcript contains one. */
function buildNativePlanHtml(automaticContext) {
  const plan = automaticContext && automaticContext.plan
  if (!plan) return ''
  const labelParts = [STRINGS.previewNativePlan]
  if (plan.source) labelParts.push(friendlySource(plan.source))
  return buildPreviewMarkdownBlockHtml(
    labelParts.join(' · '),
    plan.text,
    'preview-block--scrollable',
    '▤'
  )
}

/** Returns a compact, read-only view of Claude-native TodoWrite state. */
function buildNativeTodosHtml(automaticContext) {
  const todos = automaticContext && automaticContext.todos
  if (!todos || !Array.isArray(todos.items) || todos.items.length === 0) return ''

  const rows = todos.items
    .map(function (todo) {
      const status = todo.status || 'unknown'
      return (
        '<div class="preview-todo preview-todo--' +
        escapeHtml(status) +
        '" title="' +
        escapeHtml(status) +
        '">' +
        '<span class="preview-todo-marker">' +
        todoMarker(todo) +
        '</span>' +
        escapeHtml(todo.content) +
        '</div>'
      )
    })
    .join('')

  const summaryLabelParts = [
    STRINGS.previewNativeTodos,
    escapeHtml(
      fmt(STRINGS.previewNativeTodosSummary, {
        done: todos.counts?.completed || 0,
        open:
          (todos.counts?.pending || 0) +
          (todos.counts?.in_progress || 0) +
          (todos.counts?.unknown || 0),
      })
    ),
  ]
  if (todos.source) summaryLabelParts.push(escapeHtml(friendlySource(todos.source)))

  return (
    '<div class="preview-block preview-block--scrollable">' +
    buildPreviewLabelHtml(summaryLabelParts.join(' · '), '☑') +
    '<div class="preview-todos-body">' +
    rows +
    '</div>' +
    '</div>'
  )
}

/** Returns a compact summary of files read and research actions taken in the session. */
function buildResearchTrailHtml(automaticContext) {
  const readFiles = (automaticContext && automaticContext.readFiles) || []
  const researchActions = (automaticContext && automaticContext.researchActions) || []
  const totalCount = readFiles.length + researchActions.length
  if (totalCount === 0) return ''

  const kindPrefix = { grep: '~', glob: '*', 'web-search': '?', 'web-fetch': '→' }

  const fileRows = readFiles
    .map(function (file) {
      return (
        '<div class="preview-file" title="' +
        escapeHtml(file) +
        '">r ' +
        escapeHtml(file) +
        '</div>'
      )
    })
    .join('')

  const actionRows = researchActions
    .map(function (action) {
      const prefix = (kindPrefix[action.kind] || '?') + ' ' + escapeHtml(action.kind)
      const detail = action.query ? ': ' + escapeHtml(action.query) : ''
      return '<div class="preview-file">' + prefix + detail + '</div>'
    })
    .join('')

  return (
    '<div class="preview-block">' +
    buildPreviewLabelHtml(fmt(STRINGS.previewResearchTrail, { count: totalCount }), '⌕') +
    '<div class="preview-todos-body">' +
    fileRows +
    actionRows +
    '</div>' +
    '</div>'
  )
}

/** Returns a compact summary of tool failures and interruptions, or empty string when clean. */
function buildToolHealthHtml(automaticContext) {
  const health = automaticContext && automaticContext.toolHealth
  if (!health) return ''

  const failed = health.failed || []
  const interrupted = health.interrupted || []
  if (failed.length === 0 && interrupted.length === 0) return ''

  const summaryParts = []
  if (failed.length > 0) summaryParts.push(fmt(STRINGS.previewToolFailed, { count: failed.length }))
  if (interrupted.length > 0)
    summaryParts.push(fmt(STRINGS.previewToolInterrupted, { count: interrupted.length }))

  const failedRows = failed
    .map(function (t) {
      return '<div class="preview-file">✗ ' + escapeHtml(t.name) + '</div>'
    })
    .join('')

  const interruptedRows = interrupted
    .map(function (t) {
      return '<div class="preview-file">⚡ ' + escapeHtml(t.name) + '</div>'
    })
    .join('')

  return (
    '<div class="preview-block">' +
    buildPreviewLabelHtml(STRINGS.previewToolHealth + ' · ' + summaryParts.join(', '), '⚠') +
    failedRows +
    interruptedRows +
    '</div>'
  )
}

/** Returns the selected session's on-demand Resume Card preview HTML. */
function buildSessionPreviewHtml(project, session) {
  const entry = ensureSessionPreview(project, session)

  if (entry.state === 'loading') {
    return (
      '<div class="preview-card"><div class="preview-loading">' +
      STRINGS.previewLoading +
      '</div></div>'
    )
  }
  if (entry.state === 'error') {
    return (
      '<div class="preview-card"><div class="preview-error">' +
      escapeHtml(fmt(STRINGS.previewError, { error: entry.error || 'unknown error' })) +
      '</div></div>'
    )
  }

  const preview = entry.data || {}
  return (
    '<div class="preview-card">' +
    '<div class="preview-title">' +
    STRINGS.previewTitle +
    '</div>' +
    buildPreviewBlockHtml(STRINGS.previewGoal, preview.goal, null, '?') +
    buildPreviewMarkdownBlockHtml(
      STRINGS.previewLastResponse,
      preview.lastResponse,
      'preview-block--scrollable',
      '↳'
    ) +
    buildNativePlanHtml(preview.automaticContext) +
    buildNativeTodosHtml(preview.automaticContext) +
    buildResearchTrailHtml(preview.automaticContext) +
    buildToolHealthHtml(preview.automaticContext) +
    (preview.pendingToolName
      ? '<div class="preview-warning">' +
        escapeHtml(fmt(STRINGS.previewPendingTool, { name: preview.pendingToolName })) +
        '</div>'
      : '') +
    buildTouchedFilesHtml(preview, session) +
    '</div>'
  )
}

function todoMarker(todo) {
  if (todo.status === 'completed') return '[x]'
  if (todo.status === 'in_progress') return '[~]'
  if (todo.status === 'pending') return '[ ]'
  return '[?]'
}

function renderPreviewMarkdown(markdown) {
  const lines = String(markdown).replace(/\r\n?/g, '\n').split('\n')
  let html = ''
  let inList = false

  function closeList() {
    if (!inList) return
    html += '</ul>'
    inList = false
  }

  lines.forEach(function (rawLine) {
    const line = rawLine.trim()
    if (!line) {
      closeList()
      return
    }

    const heading = line.match(/^#{1,4}\s+(.+)$/)
    if (heading) {
      closeList()
      html += '<div class="preview-md-heading">' + renderMarkdownInline(heading[1]) + '</div>'
      return
    }

    const bullet = line.match(/^(?:[-*]|\d+\.)\s+(.+)$/)
    if (bullet) {
      if (!inList) {
        html += '<ul class="preview-md-list">'
        inList = true
      }
      html += '<li>' + renderMarkdownInline(bullet[1]) + '</li>'
      return
    }

    closeList()
    html += '<p>' + renderMarkdownInline(line) + '</p>'
  })

  closeList()
  return html || '<span class="preview-empty">' + STRINGS.previewNotFound + '</span>'
}

function renderMarkdownInline(text) {
  return String(text)
    .split(/(`[^`]+`)/g)
    .map(function (part) {
      if (part.startsWith('`') && part.endsWith('`')) {
        return '<code>' + escapeHtml(part.slice(1, -1)) + '</code>'
      }
      return escapeHtml(part).replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>')
    })
    .join('')
}

function isSessionInspectorExpanded(visibleSessions) {
  return (
    sessionInspectorExpanded &&
    selectedSession &&
    !window.matchMedia('(max-width: 639px)').matches &&
    visibleSessions.some(function (session) {
      return session.id === selectedSession.id
    })
  )
}

/**
 * Builds the compact Org section for the inspector: tags, group, stack memberships.
 * Returns "" when no org data is loaded and the session has no tags.
 */
function buildOrgInspectorHtml(session, project) {
  var tags = session.tags || []
  var assignments = (orgData && orgData.projectGroupAssignments) || {}
  var groups = (orgData && orgData.groups) || []
  var stacks = (orgData && orgData.stacks) || []

  // Find group name
  var groupId = assignments[project ? project.id : '']
  var groupName = null
  for (var gi = 0; gi < groups.length; gi++) {
    if (groups[gi].id === groupId) {
      groupName = groups[gi].name
      break
    }
  }

  // Find stacks containing this session or project
  var sessionStackNames = []
  for (var si = 0; si < stacks.length; si++) {
    var stack = stacks[si]
    var inStack = stack.items.some(function (item) {
      if (item.kind === 'project' && project && item.projectId === project.id) return true
      if (item.kind === 'session' && item.sessionId === session.id) return true
      return false
    })
    if (inStack) sessionStackNames.push(stack.name)
  }

  if (tags.length === 0 && !groupName && sessionStackNames.length === 0 && !orgData) return ''

  var html = '<div class="insp-org-section">'

  // Tags row
  html += '<div class="insp-org-row">'
  html += '<span class="insp-org-label">' + escapeHtml(STRINGS.inspOrgTags) + '</span>'
  html += '<span class="insp-org-value">'
  for (var ti = 0; ti < tags.length; ti++) {
    html +=
      '<span class="s-tag insp-tag" data-tag="' +
      escapeHtml(tags[ti]) +
      '">#' +
      escapeHtml(tags[ti]) +
      '</span>'
  }
  html +=
    '<button class="insp-org-add" data-inspector-action="session-tag">' +
    escapeHtml(STRINGS.inspOrgAddTag) +
    '</button>'
  html += '</span></div>'

  // Group row
  if (groupName || orgData) {
    html += '<div class="insp-org-row">'
    html += '<span class="insp-org-label">' + escapeHtml(STRINGS.inspOrgGroup) + '</span>'
    html +=
      '<span class="insp-org-value">' +
      (groupName
        ? '<span class="insp-org-pill">' + escapeHtml(groupName) + '</span>'
        : '<span class="insp-org-muted">' + escapeHtml(STRINGS.inspOrgNoGroup) + '</span>') +
      '<button class="insp-org-add" data-inspector-action="project-group">change</button>' +
      '</span>'
    html += '</div>'
  }

  // Stacks row
  if (sessionStackNames.length > 0 || orgData) {
    html += '<div class="insp-org-row">'
    html += '<span class="insp-org-label">' + escapeHtml(STRINGS.inspOrgStacks) + '</span>'
    html += '<span class="insp-org-value">'
    if (sessionStackNames.length > 0) {
      for (var sni = 0; sni < sessionStackNames.length; sni++) {
        html += '<span class="insp-org-pill">' + escapeHtml(sessionStackNames[sni]) + '</span>'
      }
    } else {
      html += '<span class="insp-org-muted">' + escapeHtml(STRINGS.inspOrgNoGroup) + '</span>'
    }
    html += '<button class="insp-org-add" data-inspector-action="session-stack">change</button>'
    html += '</span></div>'
  }

  html += '</div>'
  return html
}

/** Re-renders the session inspector panel for the selected session. Hides it when no selection is visible. */
function renderInspector(visibleSessions) {
  const selectionIsVisible =
    selectedSession &&
    visibleSessions.some(function (session) {
      return session.id === selectedSession.id
    })
  if (!selectionIsVisible) {
    elements.sessionInspector.style.display = 'none'
    return
  }

  const session = selectedSession
  const signals = session.signals || {}
  const descriptions = {
    interrupted: signals.interruptedByUser
      ? STRINGS.statusStoppedByUserDesc
      : STRINGS.statusInterruptedDesc,
    expiring: fmt(STRINGS.statusExpiringDesc, { days: signals.expiresInDays }),
    'path-missing': STRINGS.statusPathMissingDesc,
    'heavily-compacted': fmt(STRINGS.statusHeavilyCompactedDesc, {
      count: signals.compactionCount,
    }),
  }
  const statusDescription = descriptions[session.primaryStatus]
  const status =
    buildStatusBadgeHtml(session) ||
    '<span class="insp-status-ok">' + STRINGS.inspStatusOk + '</span>'
  const statusValue =
    status +
    (statusDescription
      ? '<span class="insp-note">' + escapeHtml(statusDescription) + '</span>'
      : '')

  let html =
    '<div class="insp-title-row">' +
    '<div class="insp-title">' +
    STRINGS.inspectorTitle +
    '</div>' +
    '<button class="insp-expand-btn" data-inspector-action="inspector-toggle-expanded" title="' +
    escapeHtml(
      sessionInspectorExpanded
        ? STRINGS.inspCollapseDetailsTooltip
        : STRINGS.inspExpandDetailsTooltip
    ) +
    '" aria-label="' +
    escapeHtml(
      sessionInspectorExpanded
        ? STRINGS.inspCollapseDetailsTooltip
        : STRINGS.inspExpandDetailsTooltip
    ) +
    '">' +
    '<span class="insp-expand-icon">' +
    (isSessionInspectorExpanded(visibleSessions) ? '▾' : '▴') +
    '</span>' +
    '<span class="insp-expand-label">' +
    (isSessionInspectorExpanded(visibleSessions)
      ? STRINGS.inspCollapseDetailsLabel
      : STRINGS.inspExpandDetailsLabel) +
    '</span>' +
    '</button>' +
    '<button class="insp-icon-btn" data-inspector-action="session-copy-id" title="' +
    escapeHtml(STRINGS.inspectorCopyId) +
    '">ID</button>' +
    '</div>'
  html += buildInspectorActionsHtml(session)
  html += buildSessionPreviewHtml(selectedProject, session)
  html += buildInspectorRowHtml(STRINGS.inspRowStatus, statusValue)
  html += buildInspectorHeartbeatHtml(session)
  html += buildInspectorRowHtml(
    STRINGS.inspRowLastActive,
    '<em>' + escapeHtml(relativeTime(session.updated)) + '</em>'
  )
  html += buildInspectorRowHtml(STRINGS.inspRowMessages, session.messageCount)
  if (signals.analysisComplete && signals.compactionCount > 0) {
    html += buildInspectorRowHtml(
      STRINGS.inspRowCompactions,
      signals.compactionCount,
      null,
      'title="' + escapeHtml(STRINGS.inspRowCompactionsTooltip) + '"'
    )
  }
  if (signals.expiresInDays != null) {
    html += buildInspectorRowHtml(
      STRINGS.inspRowExpiresIn,
      fmt(STRINGS.inspRowExpiresInValue, { days: signals.expiresInDays }),
      null,
      'title="' + escapeHtml(STRINGS.inspRowExpiresInTooltip) + '"'
    )
  }
  if (session.context.latestModel) {
    html += buildInspectorRowHtml(
      STRINGS.inspRowLatestModel,
      escapeHtml(session.context.latestModel)
    )
  }
  if (session.context.latestContextTokens != null) {
    html += buildInspectorRowHtml(
      STRINGS.inspRowLastContext,
      fmt(STRINGS.inspRowTokenValue, {
        count: formatTokenCount(session.context.latestContextTokens),
      }),
      null,
      'title="' + escapeHtml(STRINGS.inspRowLastContextTooltip) + '"'
    )
  }
  if (session.context.latestOutputTokens != null) {
    html += buildInspectorRowHtml(
      STRINGS.inspRowLastOutput,
      fmt(STRINGS.inspRowTokenValue, {
        count: formatTokenCount(session.context.latestOutputTokens),
      }),
      null,
      'title="' + escapeHtml(STRINGS.inspRowLastOutputTooltip) + '"'
    )
  }
  if (session.context.models && session.context.models.length > 1) {
    html += buildInspectorRowHtml(
      STRINGS.inspRowModelsUsed,
      escapeHtml(session.context.models.join(', ')),
      null,
      'title="' + escapeHtml(STRINGS.inspRowModelsUsedTooltip) + '"'
    )
  }
  html += buildInspectorRowHtml(
    STRINGS.inspRowSessionId,
    session.id.slice(0, 8) + '...',
    'insp-copy',
    'title="' +
      escapeHtml(STRINGS.inspRowSessionIdTooltip) +
      '" data-copy="' +
      escapeHtml(session.id) +
      '"'
  )
  html += buildInspectorRowHtml(
    STRINGS.inspRowPath,
    escapeHtml(session.projectPath),
    'insp-path',
    'title="' + escapeHtml(session.projectPath) + '"'
  )
  html += buildOrgInspectorHtml(session, selectedProject)

  elements.sessionInspector.innerHTML = html
  elements.sessionInspector.style.display = 'block'
}

elements.sessionInspector.addEventListener('click', function (event) {
  // Tag chip in org section — set tag focus filter
  const inspTag = event.target.closest('.insp-tag')
  if (inspTag) {
    var tag = inspTag.dataset.tag
    if (tag) {
      focusFilter =
        focusFilter && focusFilter.kind === 'tag' && focusFilter.tag === tag
          ? null
          : { kind: 'tag', tag: tag }
      renderRail()
      renderFocusBar()
      renderProjects()
      renderSessions()
    }
    return
  }

  const actionButton = event.target.closest('[data-inspector-action]')
  if (actionButton && selectedSession) {
    var inspectorAction = actionButton.dataset.inspectorAction
    if (inspectorAction === 'inspector-toggle-expanded') {
      sessionInspectorExpanded = !sessionInspectorExpanded
      renderSessions()
      return
    }
    if (inspectorAction === 'project-group' && selectedProject) {
      openGroupPicker(selectedProject)
      return
    }
    if (inspectorAction === 'session-stack' && selectedProject) {
      openStackPicker(selectedProject, selectedSession)
      return
    }
    executeSessionAction(inspectorAction, selectedSession)
    return
  }

  const copyTarget = event.target.closest('.insp-copy')
  const text = copyTarget && copyTarget.dataset.copy
  if (!text) return

  copyTextToClipboard(text, fmt(STRINGS.inspCopied, { prefix: text.slice(0, 20) }))
})

elements.filterBar.addEventListener('click', function (event) {
  const pill = event.target.closest('.filter-pill')
  if (!pill) return
  selectedFilter = pill.dataset.filter || 'all'
  synchronizeSelectedProjectWithView()
  renderProjects()
  renderSessions()
})

elements.sortSelect.addEventListener('change', function () {
  selectedSort = elements.sortSelect.value
  renderSessions()
})
// ---------------------------------------------------------------------------
// Session list rendering and metadata actions
// ---------------------------------------------------------------------------

const TAG_CHIPS_MAX = 2

/**
 * Renders up to TAG_CHIPS_MAX tag chips for a session, with a "+N" overflow badge.
 * Returns "" when there are no tags.
 */
function buildTagChipsHtml(tags) {
  if (!tags || tags.length === 0) return ''
  var shown = tags.slice(0, TAG_CHIPS_MAX)
  var overflow = tags.length - shown.length
  var html = '<span class="s-tags">'
  for (var i = 0; i < shown.length; i++) {
    html +=
      '<span class="s-tag" data-tag="' +
      escapeHtml(shown[i]) +
      '">#' +
      escapeHtml(shown[i]) +
      '</span>'
  }
  if (overflow > 0) {
    html +=
      '<span class="s-tag-overflow">' + fmt(STRINGS.tagChipOverflow, { n: overflow }) + '</span>'
  }
  html += '</span>'
  return html
}

/**
 * Resolves the dot state for a live session row, from the same helper the rail
 * and the inspector use. Falls back to "idle" when the session is live but has
 * no live-activity entry yet (a brief gap right after activeSessionIds
 * updates, before the next snapshot).
 */
function liveSessionRowState(sessionId) {
  const state = dotActivityState(findLiveActivity(sessionId))
  return { label: dotActivityLabel(state), state }
}

/** Renders a single session row (two lines + optional deep-search snippet) as an HTML string. */
function buildSessionRowHtml(session) {
  const isSelected = selectedSession && session.id === selectedSession.id
  const branch = session.gitBranch || null
  const displayName = session.alias || session.name
  const isLive = activeSessionIds.has(session.id)
  const liveState = isLive ? liveSessionRowState(session.id) : null

  return (
    '<div class="sess-row' +
    (isSelected ? ' sel' : '') +
    (session.signals.archived ? ' archived' : '') +
    '" data-session-id="' +
    escapeHtml(session.id) +
    '">' +
    '<div class="s-line1">' +
    '<span class="s-arrow">' +
    (isSelected ? '▶' : ' ') +
    '</span>' +
    '<span class="s-live"' +
    (liveState ? ' title="' + escapeHtml(liveState.label) + '"' : '') +
    '>' +
    (liveState ? '<span class="activity-dot ' + escapeHtml(liveState.state) + '"></span>' : '') +
    '</span>' +
    (renamingSessionId === session.id
      ? '<input class="s-rename-input" value="' + escapeHtml(displayName) + '" maxlength="160">'
      : '<span class="s-name">' + escapeHtml(displayName) + '</span>') +
    '<span class="s-time" title="' +
    escapeHtml(
      fmt(STRINGS.sessionTimeTooltip, { date: new Date(session.updated).toLocaleString() })
    ) +
    '">' +
    relativeTime(session.updated) +
    '</span>' +
    '<button class="s-menu-btn" title="' +
    escapeHtml(STRINGS.sessionMoreActions) +
    '">⋯</button>' +
    '</div>' +
    '<div class="s-line2">' +
    (branch
      ? '<span class="branch-n" style="color:' +
        colorForGitBranch(branch) +
        '" title="' +
        escapeHtml(fmt(STRINGS.sessionBranchTooltip, { branch: branch })) +
        '">⎇ ' +
        escapeHtml(branch) +
        '</span>' +
        buildBranchDriftHtml(session) +
        '<span class="s-sep">·</span>'
      : '') +
    '<span class="s-msgs">' +
    session.messageCount +
    ' msgs</span>' +
    (session.context.latestModel
      ? '<span class="s-model" title="' +
        escapeHtml(fmt(STRINGS.sessionModelTooltip, { model: session.context.latestModel })) +
        '">' +
        escapeHtml(session.context.latestModel) +
        '</span>'
      : '') +
    (session.context.latestContextTokens != null
      ? '<span class="s-context" title="' +
        escapeHtml(
          fmt(STRINGS.sessionContextTooltip, {
            tokens: formatTokenCount(session.context.latestContextTokens),
          })
        ) +
        '">' +
        formatTokenCount(session.context.latestContextTokens) +
        ' ctx</span>'
      : '') +
    buildStatusBadgeHtml(session) +
    buildTagChipsHtml(session.tags) +
    '</div>' +
    (deepSearchActive ? buildDeepSnippetHtml(getDeepMatchForSession(session.id)) : '') +
    '</div>'
  )
}

/** Returns an empty-state HTML message when there are no sessions to show, or "" when there are. */
function buildEmptySessionListHtml(visibleSessions) {
  if (!selectedProject) {
    return searchQuery
      ? '<div class="empty">' + STRINGS.emptyNoMatch + '</div>'
      : '<div class="empty">' + STRINGS.emptySelectProject + '</div>'
  }
  if (visibleSessions.length > 0) return ''

  const archivedCount = sessionsMatchingFilter(selectedProject, 'archived').length
  const message = searchQuery
    ? STRINGS.emptyNoSessionsSearch
    : selectedFilter === 'all'
      ? STRINGS.emptyNoSessions
      : STRINGS.emptyNoSessionsFilter
  const archiveHint =
    selectedFilter === 'all' && archivedCount > 0
      ? ' <span class="empty-hint">' +
        fmt(STRINGS.emptyArchivedHint, { n: archivedCount }) +
        '</span>'
      : ''
  return '<div class="empty">' + message + archiveHint + '</div>'
}

function countReviewBucketSessionsForProject(project, bucket) {
  if (!project) return 0
  var count = 0
  for (var i = 0; i < project.sessions.length; i++) {
    var session = project.sessions[i]
    if (!session.signals.archived && bucket.test(session)) count++
  }
  return count
}

function applyReviewSearchToken(token) {
  if (deepSearchActive) exitInlineDeepSearch()
  openSearch()
  searchQuery = token
  selectedFilter = 'all'
  elements.searchInput.value = token
  elements.searchInput.focus()
  synchronizeSelectedProjectWithView()
  renderProjects()
  renderSessions()
}

function renderReviewSignals() {
  if (!elements.reviewSignals) return
  if (!selectedProject || deepSearchActive) {
    elements.reviewSignals.style.display = 'none'
    elements.reviewSignals.innerHTML = ''
    return
  }

  var html = ''
  for (var i = 0; i < REVIEW_BUCKETS.length; i++) {
    var bucket = REVIEW_BUCKETS[i]
    var count = countReviewBucketSessionsForProject(selectedProject, bucket)
    if (count === 0) continue

    var label = STRINGS[bucket.labelKey] || bucket.id
    var countLabel = count === 1 ? '1 session' : count + ' sessions'
    var tooltip = fmt(STRINGS.reviewSignalTooltip, {
      count: countLabel,
      label: label,
      token: bucket.searchToken,
    })
    html +=
      '<button class="review-signal ' +
      bucket.cssClass +
      '" data-review-token="' +
      escapeHtml(bucket.searchToken) +
      '" data-tooltip="' +
      escapeHtml(tooltip) +
      '" aria-label="' +
      escapeHtml(tooltip) +
      '">' +
      bucket.icon +
      '</button>'
  }

  elements.reviewSignals.innerHTML = html
  elements.reviewSignals.style.display = html ? 'flex' : 'none'
}

/** Re-renders the session list, panel header, filter bar, and inspector from current state. */
function renderSessions() {
  const visibleSessions = deriveVisibleSessions()
  synchronizeSelectedSession()
  const inspectorIsExpanded = isSessionInspectorExpanded(visibleSessions)
  const listedSessions = inspectorIsExpanded ? [selectedSession] : visibleSessions
  document.body.classList.toggle('session-details-expanded', inspectorIsExpanded)

  if (deepSearchActive) {
    elements.sessionPanelTitle.textContent = deepSearchLoading
      ? STRINGS.sessionSearching
      : '⌕ ' + deepSearchQueryTerm
    elements.sessionCount.textContent = deepSearchLoading
      ? ''
      : fmt(STRINGS.sessionDeepFound, { n: deepSearchMatches.length })
  } else {
    elements.sessionPanelTitle.textContent = selectedProject
      ? compactPath(selectedProject.path)
      : STRINGS.sessionPanelPlaceholder
    elements.sessionCount.textContent = selectedProject
      ? fmt(STRINGS.sessionCountLabel, { n: visibleSessions.length })
      : ''
  }
  renderReviewSignals()
  renderFilterBar()
  renderInspector(visibleSessions)

  if (deepSearchActive && deepSearchLoading) {
    elements.sessionList.innerHTML = matrixSoftLoaderHtml(STRINGS.sessionSearching)
  } else {
    const emptyHtml = buildEmptySessionListHtml(visibleSessions)
    elements.sessionList.innerHTML = emptyHtml || listedSessions.map(buildSessionRowHtml).join('')
  }

  if (renamingSessionId) {
    const input = elements.sessionList.querySelector('.s-rename-input')
    if (input) {
      input.focus()
      input.select()
    }
  }
}

if (elements.reviewSignals) {
  elements.reviewSignals.addEventListener('click', function (event) {
    var button = event.target.closest('.review-signal')
    if (!button) return
    var token = button.dataset.reviewToken
    if (token) applyReviewSearchToken(token)
  })
}

/** Persists a session alias to the server, then refreshes and shows a toast. Clears alias when empty. */
async function saveSessionAlias(session, aliasInput) {
  renamingSessionId = null
  const alias = aliasInput.trim().slice(0, 160)

  try {
    await requestJson('/api/sessions/' + selectedProject.id + '/' + session.id + '/alias', {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ alias: alias || null }),
    })
    await refreshProjectData()
    showToast(alias ? fmt(STRINGS.sessionRenamed, { alias: alias }) : STRINGS.sessionAliasCleared)
  } catch (error) {
    await refreshProjectData()
    showToast(fmt(STRINGS.sessionRenameFailed, { error: error.message }), 'err')
  }
}

async function deleteSessionPermanently(session) {
  if (activeSessionIds.has(session.id)) {
    showToast(STRINGS.sessionCannotDeleteActive, 'err')
    return
  }
  const confirmed = window.confirm(
    fmt(STRINGS.sessionDeleteConfirm, { name: session.alias || session.name })
  )
  if (!confirmed) return
  try {
    await requestJson('/api/sessions/' + selectedProject.id + '/' + session.id, {
      method: 'DELETE',
    })
    await refreshProjectData()
    showToast(STRINGS.sessionDeleted)
  } catch (error) {
    showToast(fmt(STRINGS.sessionDeleteFailed, { error: error.message }), 'err')
  }
}

/** Toggles the local archive flag on a session and refreshes. Note: Claude may still delete the transcript. */
async function toggleSessionArchivedState(session) {
  const shouldArchive = !session.signals.archived
  try {
    await requestJson('/api/sessions/' + selectedProject.id + '/' + session.id + '/archive', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ archived: shouldArchive }),
    })
    await refreshProjectData()
    if (shouldArchive) showToast(STRINGS.sessionArchivedNote)
  } catch (error) {
    showToast(fmt(STRINGS.sessionArchiveFailed, { error: error.message }), 'err')
  }
}

/** Starts inline rename mode for a session row. */
function beginSessionRename(session) {
  renamingSessionId = session.id
  renderSessions()
}

/** Copies the full session ID to the clipboard. */
function copySessionId(session) {
  copyTextToClipboard(session.id, fmt(STRINGS.sessionCopiedId, { prefix: session.id.slice(0, 8) }))
}

/** Builds a Markdown handoff packet on the server and copies it to the clipboard. */
async function copySessionHandoff(session) {
  if (!selectedProject) return
  try {
    showToast(STRINGS.sessionHandoffBuilding)
    const result = await requestJson(
      '/api/sessions/' + selectedProject.id + '/' + session.id + '/handoff'
    )
    copyTextToClipboard(result.markdown, STRINGS.sessionHandoffCopied)
  } catch (error) {
    showToast(fmt(STRINGS.sessionHandoffFailed, { error: error.message }), 'err')
  }
}

/** Executes a named session action from buttons, menus, or keyboard shortcuts. */
function executeSessionAction(action, session) {
  if (!session) return
  if (action === 'session-resume') {
    selectSession(session)
    if (shouldConfirmResume()) openResumeDialog(session)
    else void resumeSelectedSession()
  } else if (action === 'session-rename') {
    beginSessionRename(session)
  } else if (action === 'session-archive') {
    void toggleSessionArchivedState(session)
  } else if (action === 'session-delete') {
    void deleteSessionPermanently(session)
  } else if (action === 'session-copy-id') {
    copySessionId(session)
  } else if (action === 'session-handoff') {
    void copySessionHandoff(session)
  } else if (action === 'session-tag') {
    openTagPicker(session, selectedProject)
  } else if (action === 'session-add-stack') {
    openStackPicker(selectedProject, session)
  }
}

/** Returns the menu/action labels for a session in a single canonical order. */
function sessionActionItems(session) {
  return [
    {
      action: 'session-resume',
      disabled: !session.signals.pathExists,
      label: STRINGS.sessionActionResume,
    },
    { action: 'session-handoff', label: STRINGS.sessionActionHandoff },
    { type: 'separator' },
    { action: 'session-rename', label: STRINGS.sessionActionRename },
    { action: 'session-tag', label: STRINGS.sessionActionTag },
    { action: 'session-add-stack', label: STRINGS.sessionActionAddToStack },
    {
      action: 'session-archive',
      label: session.signals.archived
        ? STRINGS.sessionActionUnarchive
        : STRINGS.sessionActionArchive,
    },
    { type: 'separator' },
    { action: 'session-copy-id', label: STRINGS.sessionActionCopyId },
    { action: 'session-delete', label: STRINGS.sessionActionDelete, danger: true },
  ]
}

// Event delegation keeps handlers valid when renderSessions replaces rows.
elements.sessionList.addEventListener('click', function (event) {
  // Tag chip click — set tag focus filter
  const tagChip = event.target.closest('.s-tag')
  if (tagChip) {
    event.stopPropagation()
    var tag = tagChip.dataset.tag
    if (tag) {
      focusFilter =
        focusFilter && focusFilter.kind === 'tag' && focusFilter.tag === tag
          ? null
          : { kind: 'tag', tag: tag }
      renderRail()
      renderFocusBar()
      renderProjects()
      renderSessions()
    }
    return
  }

  const menuBtn = event.target.closest('.s-menu-btn')
  if (menuBtn) {
    event.stopPropagation()
    const session = resolveSessionFromRow(menuBtn.closest('.sess-row'))
    if (!session) return
    ctxSession = session
    ctxProject = null
    openContextMenu(menuBtn, sessionActionItems(session))
    return
  }

  const row = event.target.closest('.sess-row')
  if (!row || event.target.closest('.s-rename-input')) return

  // Clicking the row being renamed must leave its input node and typed value
  // untouched. Clicking elsewhere exits rename mode before normal selection.
  if (renamingSessionId) {
    if (row.dataset.sessionId === renamingSessionId) return
    renamingSessionId = null
    renderSessions()
    return
  }

  const session = resolveSessionFromRow(row)
  if (!session || (selectedSession && selectedSession.id === session.id)) return
  selectSession(session)
})

elements.sessionList.addEventListener('keydown', function (event) {
  if (!event.target.classList.contains('s-rename-input')) return
  const session = resolveSessionFromRow(event.target.closest('.sess-row'))
  if (!session) return

  if (event.key === 'Enter') {
    event.preventDefault()
    void saveSessionAlias(session, event.target.value)
  } else if (event.key === 'Escape') {
    renamingSessionId = null
    renderSessions()
  }
})

elements.sessionList.addEventListener(
  'blur',
  function (event) {
    if (!event.target.classList.contains('s-rename-input')) return
    // Blur fires before a related click. Let the click handler cancel or move
    // rename mode before committing the input value.
    setTimeout(function () {
      if (!renamingSessionId) return
      const session = resolveSessionFromRow(event.target.closest('.sess-row'))
      if (session) void saveSessionAlias(session, event.target.value)
    }, 150)
  },
  true
)

elements.sessionList.addEventListener('dblclick', function (event) {
  if (event.target.closest('.s-rename-input')) return
  const session = resolveSessionFromRow(event.target.closest('.sess-row'))
  if (!session) return

  if (shouldConfirmResume()) openResumeDialog(session)
  else {
    selectSession(session)
    void resumeSelectedSession()
  }
})
// ---------------------------------------------------------------------------
// Resume dialog and terminal launch
// ---------------------------------------------------------------------------

/** Opens the resume confirmation dialog pre-populated with the session details. */
function openResumeDialog(session) {
  if (!session.signals.pathExists) {
    showToast(STRINGS.resumePathUnavailable, 'err')
    return
  }
  selectSession(session)
  elements.resumeCommand.textContent = 'claude --resume ' + session.id
  elements.resumeDialogName.textContent = session.name
  elements.resumeDialogBranch.textContent = session.gitBranch ? '⎇ ' + session.gitBranch : ''
  elements.resumeDialogMessage.textContent = ''
  elements.resumeConfirmButton.textContent = STRINGS.resumeConfirmBtn
  elements.resumeConfirmButton.disabled = false
  elements.resumeOverlay.classList.add('open')
  elements.resumeConfirmButton.focus()
}

function closeResumeDialog() {
  elements.resumeOverlay.classList.remove('open')
}

/**
 * Disables the confirm button and starts a "launching…" dot animation.
 * Returns the setInterval handle so the caller can stop it with stopLaunchAnimation.
 */
function startLaunchAnimation() {
  const labels = STRINGS.resumeLaunchingFrames
  let frame = 0

  elements.resumeConfirmButton.disabled = true
  elements.resumeDialogMessage.textContent = ''
  elements.resumeConfirmButton.textContent = labels[frame]

  return setInterval(function () {
    frame = (frame + 1) % labels.length
    elements.resumeConfirmButton.textContent = labels[frame]
  }, 300)
}

/** Stops the launch animation and restores the confirm button to its default state. */
function stopLaunchAnimation(launchAnimationTimer) {
  clearInterval(launchAnimationTimer)
  elements.resumeConfirmButton.textContent = STRINGS.resumeConfirmBtn
  elements.resumeConfirmButton.disabled = false
}

/**
 * Asks the server to open the selected session in a terminal.
 * Falls back gracefully: when the terminal launch fails, the server copies the
 * resume command to the clipboard and returns copied=true so the user can paste it.
 */
async function resumeSelectedSession() {
  if (!selectedSession || !selectedProject) return
  if (!selectedSession.signals.pathExists) {
    elements.resumeDialogMessage.textContent = STRINGS.resumePathUnavailable
    if (elements.resumeOverlay.classList.contains('open')) {
      elements.resumeConfirmButton.disabled = true
    }
    showToast(STRINGS.resumePathUnavailable, 'err')
    return
  }
  const launchAnimationTimer = startLaunchAnimation()

  try {
    const launchResult = await requestJson('/api/resume/' + selectedSession.id, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ projectId: selectedProject.id }),
    })
    stopLaunchAnimation(launchAnimationTimer)

    if (launchResult.launched) {
      closeResumeDialog()
      showToast(STRINGS.resumeResumed)
    } else if (launchResult.copied && launchResult.message) {
      elements.resumeDialogMessage.textContent = fmt(STRINGS.resumeLaunchFailed, {
        message: launchResult.message,
      })
    } else if (launchResult.copied) {
      closeResumeDialog()
      showToast(STRINGS.resumeCommandCopied, 'copied')
    } else {
      elements.resumeDialogMessage.textContent =
        launchResult.message || STRINGS.resumeFallbackFailed
    }
  } catch (error) {
    stopLaunchAnimation(launchAnimationTimer)
    elements.resumeDialogMessage.textContent = fmt(STRINGS.resumeError, { message: error.message })
  }
}

elements.resumeConfirmButton.addEventListener('click', function () {
  void resumeSelectedSession()
})
elements.resumeCancelButton.addEventListener('click', closeResumeDialog)
elements.resumeOverlay.addEventListener('click', function (event) {
  if (event.target === elements.resumeOverlay) closeResumeDialog()
})
elements.alwaysConfirmCheckbox.checked = shouldConfirmResume()
elements.alwaysConfirmCheckbox.addEventListener('change', function () {
  localStorage.setItem(
    CONFIRM_RESUME_PREFERENCE,
    elements.alwaysConfirmCheckbox.checked ? 'true' : 'false'
  )
})
